stencil upx_even(vector#2 double X){
	return X@[-1,0] * 0.25 + X * 0.75;
}
stencil upx_odd(vector#2 double X){
	return X@[1,0] * 0.25 + X * 0.75;
}	
parameter M,N;	
vector#2 double input[M,N];
return ( @[(0,2),(0,1)] = upx_even(input);
         @[(1,2),(0,1)] = upx_odd(input); );

