stencil simple(vector#2 float X, vector#2 float Y){
   return X@[-3,-2] + X@[2,3] + Y@[-2,-3] + Y@[3,2];
}
parameter M,N;
vector#2 float input1[M,N];
vector#2 float input2[M,N];
return simple(input1,input2);

