#include <cstdlib>
#include <cstdio>
#include <cmath>

#define M 11
#define N 14

extern "C" void stencil_sampling(double*,int,int,double*);

// extern "C"
// void *__formart_alloc(size_t size) {
//   return new char[size];
// }

void ref_output(double* input, double * output)
{
  for( int i = 1; i < M/2 ; i++ ) 
    for( int j = 0 ; j < N/3-2 ; j++ )
      output[i*(N/3)+j] = input[(2*i-1)*N+3*j+5];
}


int main(int argc, char** argv)
{
  double * input = new double[M*N];
  double * output = new double[(M/2)*(N/3)];
  double * output_ref = new double[(M/2)*(N/3)];

  for( int i = 0 ; i < M ; i++ )
    for( int j = 0 ; j < N ; j++ )
      input[i*N+j] = (double)(rand()) / (double)(RAND_MAX-1);

  for( int i = 0 ; i < M/2 ; i++ ) 
    for( int j = 0 ; j < N/3 ; j++ ){
      output[i*(N/3)+j] = 0.0;
      output_ref[i*(N/3)+j] = 0.0;
    }

  stencil_sampling(input,M,N,output);
  ref_output(input,output_ref);

  printf("Output[%d,%d] :\n",M/2,N/3);
  for( int i = 0 ; i < M/2 ; i++ ){
    for( int j = 0 ; j < N/3 ; j++ )
      printf(" %f",output[i*(N/3)+j]);
    printf("\n");
  }
  printf("OutputRef[%d,%d] :\n",M/2,N/3);
  for( int i = 0 ; i < M/2 ; i++ ){
    for( int j = 0 ; j < N/3 ; j++ )
      printf(" %f",output_ref[i*(N/3)+j]);
    printf("\n");
  }
  double diff = 0.0;
  for( int i = 0 ; i < M/2 ; i++ )
    for( int j = 0 ; j < N/3 ; j++ )
      diff += fabs(output_ref[i*(N/3)+j] - output[i*(N/3)+j]);
  printf("Diff : %f\n",diff);
  if( diff != 0 )
    exit(1);

  delete[] input;
  delete[] output;
  delete[] output_ref;
  return 0;
}

