#include <cmath>

#define N 10
#define M 12

extern "C"
void simple_stencil(float*, float*, int, int, float*);

// extern "C"
// void *__formart_alloc(size_t size) {
//   return new char[size];
// }

void ref_output(float * input1, float* input2, float * output)
{
  for( int i = 3 ; i < M - 3 ; i++ )
    for( int j = 3 ; j < N - 3; j++ ){
      int i_index_1,j_index_1,i_index_2,j_index_2;
      i_index_1 = i-2;
      j_index_1 = j-3;
      i_index_2 = i+3;
      j_index_2 = j+2;

      output[i*N+j] = input1[(i-3)*N+j-2] + input1[(i+2)*N+j+3]
	+ input2[(i_index_1)*N+j_index_1] + input2[(i_index_2)*N+j_index_2]; 
    }
}


int main() {
  float* inp1 = new float[M*N];
  float* inp2 = new float[M*N];
  float* outp = new float[M*N];
  float* outp_ref = new float[M*N];

  for( int i = 0 ; i < M ; i++ )
    for( int j = 0 ; j < N ; j++ ){
      inp1[i*N+j] = (float)rand() / (float)RAND_MAX;
      inp2[i*N+j] = (float)rand() / (float)RAND_MAX;
      outp[i*N+j] = 0.0;
      outp_ref[i*N+j] = 0.0;
    }

  simple_stencil(inp1,inp2,M,N,outp);
  ref_output(inp1,inp2,outp_ref);

  printf("Output :\n");
  for( int i = 0 ; i < M ; i++ ){
    for( int j = 0 ; j < N ; j++ )
      printf(" %f", outp[i*N+j]);
    printf("\n");
  }
  printf("Output-Ref :\n");
  for( int i = 0 ; i < M ; i++ ){
    for( int j = 0 ; j < N ; j++ )
      printf(" %f", outp_ref[i*N+j]);
    printf("\n");
  }
  double diff = 0.0;
  for( int i = 0 ; i < M ; i++) 
    for( int j = 0 ; j < N ; j++ )
      diff += fabs(outp_ref[i*N+j] - outp[i*N+j]);
  printf("Diff : %e\n",diff);
  if (diff > 1e-5) {
    printf("Incorrect Result\n");
    exit(1);
  }
  delete[] inp1;
  delete[] inp2;
  delete[] outp;
  delete[] outp_ref;
}

